/** Look up one route's metadata by key. Throws early on a typo. */
export function seoMeta(key) {
    const found = SEO_ROUTES.find((r) => r.key === key);
    if (!found) throw new Error(`Unknown SEO route key: ${key}`);
    return found;
}
